#!/usr/bin/env python3
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
sports=json.loads((ROOT/'data/sports.json').read_text())

def nav(base,active=''):
    sportlinks=''.join(f'<a class="{"active" if active==s["slug"] else ""}" href="{base}/sports/{s["slug"]}.html"><span>{s["icon"]}</span>{s["name"]}</a>' for s in sports)
    return f'''<aside class="sidebar"><a class="brand" href="{base}/"><span class="brand-mark">O</span><span><strong>Research Desk</strong><small>OLBG market monitor</small></span></a><nav class="nav"><div class="nav-label">Workspace</div><a href="{base}/">⌂ &nbsp;Executive summary</a><a href="{base}/review.html">⚑ &nbsp;Flagged for review</a><a href="{base}/methodology.html">◈ &nbsp;Pricing playbook</a><div class="nav-label">Covered sports</div>{sportlinks}</nav></aside>'''

def frame(body,base='.',active='',page='',sport=''):
 return f'''<!doctype html><html lang="en" data-base="{base}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Auditable OLBG sports market research dashboard"><title>OLBG Research Desk</title><link rel="stylesheet" href="{base}/assets/styles.css"></head><body data-page="{page}" data-sport="{sport}"><div class="shell">{nav(base,active)}<main class="main"><header class="topbar"><a class="brand mobile-nav" href="{base}/"><span class="brand-mark">O</span></a><span class="eyebrow">Independent market research</span><span class="status"><i></i>Snapshot · 26 Oct 2026 UTC</span></header><div class="content">{body}<footer class="footer">For research only · 18+ · No outcome is guaranteed. Source status is shown per row. Blank means not confirmed, never inferred.</footer></div></main></div><script src="{base}/assets/app.js"></script></body></html>'''

table='''<div class="card table-card"><div class="table-tools"><input class="search" data-search-input placeholder="Search events or selections…" aria-label="Search listings"><span class="sub">Times reproduced exactly as dated in this snapshot</span></div><table><thead><tr><th>Event</th><th>Start</th><th>Market</th><th>OLBG display</th><th>Our line / pick</th><th>Status</th><th>Sources</th></tr></thead><tbody id="events-body"></tbody></table></div>'''
home=f'''<section class="hero"><div><span class="eyebrow">Executive summary</span><h1>Clear markets.<br>Evidence before picks.</h1><p>A focused view of the 15 requested OLBG sports. Listings are separated from original recommendations so community sentiment is never presented as our own analysis.</p></div><div class="stamp"><strong>Research snapshot</strong>26 October 2026 · UTC<br>Source observations are time-sensitive</div></section><div class="alert"><span>⚠</span><div><strong>No high-confidence picks are published.</strong>These listings were observed on OLBG, but official event pages, confirmed lineups/injuries, complete pricing inputs and market odds were not all independently confirmed. In accordance with the verification rule, our line, fair odds, confidence and written prediction remain blank.</div></div><section class="kpis"><div class="kpi"><span>Sports covered</span><strong id="sport-count">15</strong><em>requested categories</em></div><div class="kpi"><span>OLBG listings captured</span><strong id="listing-count">—</strong><em>source-linked snapshot</em></div><div class="kpi"><span>Publishable picks</span><strong>0</strong><em>verification gate enforced</em></div><div class="kpi"><span>Unverified</span><strong>100%</strong><em>clearly flagged</em></div></section><div class="section-head"><div><span class="eyebrow">Coverage</span><h2>Explore by sport</h2></div><p>Pricing approach and observed markets</p></div><div class="sports-grid" id="sport-grid"></div><div class="section-head"><div><span class="eyebrow">Source ledger</span><h2>Observed upcoming listings</h2></div><p>OLBG is a discovery source, not official confirmation</p></div>{table}'''
(ROOT/'index.html').write_text(frame(home,page='home'))
for s in sports:
 body=f'''<section class="hero"><div><span class="eyebrow">Sport desk</span><h1><span id="sport-icon">{s['icon']}</span> <span id="sport-title">{s['name']}</span></h1><p id="markets">{s['markets']}</p></div><div class="stamp"><strong><span id="listing-count">—</span> observed listings</strong><a class="link" id="olbg-page" href="{s['olbg']}" target="_blank" rel="noopener">Open OLBG sport page ↗</a></div></section><div class="alert"><span>⚠</span><div><strong>Verification gate active.</strong>An OLBG entry is not a recommendation. A pick appears only after an official event source, current inputs and an independently originated price are recorded.</div></div><section class="card method"><span class="eyebrow">Origination framework</span><h2>How this sport should be priced</h2><p id="pricing">{s['pricing']}</p><div class="callout"><strong>Release rule</strong><p>Publish only when fair probability exceeds 70%, offered American odds are between −250 and +10000, the edge survives uncertainty, and every factual sentence has an official source.</p></div></section><div class="section-head"><div><span class="eyebrow">Event ledger</span><h2>OLBG listings</h2></div></div>{table}'''
 (ROOT/'sports'/f'{s["slug"]}.html').write_text(frame(body,'..',s['slug'],'sport',s['slug']))
review='''<section class="hero"><div><span class="eyebrow">Quality control</span><h1>Flagged for review</h1><p>Transparent exceptions and unresolved source gaps. These items do not qualify as predictions.</p></div></section><div class="alert"><span>⚑</span><div><strong>All captured rows are currently flagged.</strong>OLBG pages confirm what OLBG displayed at collection time, but they are not official governing-body schedule, roster, injury or result sources.</div></div><section class="card method"><h2>Open irregularities</h2><table><thead><tr><th>Issue</th><th>Impact</th><th>Disposition</th></tr></thead><tbody><tr><td><strong>Official event confirmation absent</strong><span class="sub">All event rows</span></td><td>Date, time and participants cannot be labeled independently confirmed.</td><td><span class="badge flag">Blocked</span> Keep original line and pick blank.</td></tr><tr><td><strong>Timezone not exposed consistently</strong><span class="sub">OLBG uses “Today” / “Tomorrow” in places</span></td><td>Displayed time may depend on site locale.</td><td><span class="badge flag">Flagged</span> Snapshot dates are explicit and retain “OLBG display”.</td></tr><tr><td><strong>Handball tie concentration</strong><span class="sub">Several OLBG rows show “Tie” as popular moneyline selection</span></td><td>Could reflect market/UI semantics rather than reliable consensus.</td><td><span class="badge flag">Needs review</span> No inference made.</td></tr><tr><td><strong>No current market odds in captured output</strong></td><td>−250 to +10000 eligibility and value cannot be tested.</td><td><span class="badge flag">Blocked</span> Fair odds and edge remain blank.</td></tr><tr><td><strong>Fewer than five listings in some sports</strong></td><td>The requested daily quota cannot be met honestly where OLBG shows fewer events or no tips.</td><td><span class="badge flag">Disclosed</span> Never fabricate inventory.</td></tr></tbody></table></section>'''
(ROOT/'review.html').write_text(frame(review))
methods=''.join(f'<section class="card method" id="{s["slug"]}"><span class="eyebrow">{s["name"]}</span><h3>{s["markets"]}</h3><p>{s["pricing"]}</p></section>' for s in sports)
method=f'''<section class="hero"><div><span class="eyebrow">Pricing playbook</span><h1>One audit trail for every line.</h1><p>Sport-specific inputs differ; publication controls do not.</p></div></section><section class="card method"><h2>Universal release pipeline</h2><p><strong>1. Discover</strong> an OLBG event → <strong>2. Confirm</strong> it on the organizer, league or governing-body site → <strong>3. Record</strong> timestamped form, availability and event conditions → <strong>4. Price</strong> every supported outcome → <strong>5. Remove margin</strong> from comparison odds → <strong>6. Stress-test</strong> uncertainty → <strong>7. Publish</strong> only eligible high-confidence edges.</p><div class="callout"><strong>Confidence bands</strong><p>High: ≥70% fair probability and evidence complete. Medium: 55–69.9%. Low: &lt;55%. Confidence is probability, not certainty. Missing official evidence overrides the band and blocks publication.</p></div><p><strong>American fair odds:</strong> for probability p ≥ 0.5, −100p/(1−p); otherwise +100(1−p)/p. Preserve full precision internally and round only for display.</p></section><div class="section-head"><h2>Sport-by-sport methods</h2></div>{methods}'''
(ROOT/'methodology.html').write_text(frame(method))
print(f'Built {len(sports)+3} pages')
